\documentclass{article}
% A1 portrait: 594mm x 841mm
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Color Theme: Warm Parchment & Aged Ink ──
\definecolor{primary}{HTML}{3E2723}       % deep aged-ink brown
\definecolor{secondary}{HTML}{795548}     % warm medium brown
\definecolor{accent}{HTML}{BF360C}        % burnt orange-red
\definecolor{bgposter}{HTML}{F5F0E8}      % warm parchment background
\definecolor{cardbgA}{HTML}{EFEBE9}       % warm cream tint
\definecolor{cardbgB}{HTML}{FFF3E0}       % warm amber tint
\definecolor{cardbgC}{HTML}{FBE9E7}       % warm rose tint
\definecolor{titlebgA}{HTML}{4E342E}      % title bar dark brown
\definecolor{stathighlight}{HTML}{FBE9E7} % stat callout bg
\definecolor{textdark}{HTML}{3E2723}      % main text
\definecolor{textgray}{HTML}{5D4037}      % secondary text
\definecolor{goldaccent}{HTML}{E65100}    % gold-orange for emphasis

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=5pt, parsep=2pt, topsep=2pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=5pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[2mm]
  {\fontsize{18}{22}\selectfont\color{textgray}\textit{#3}}\vspace{1mm}%
}

% ── Card styles (left accent stripe) ──
\tcbset{
  browncard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbgA,
    borderline west={4pt}{0pt}{primary},
    left=12pt, right=10pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{26}{32}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=cardbgA,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=1.5pt, titlerule style={primary!40},
    valign=top, drop shadow={opacity=0.15},
  },
  orangecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbgB,
    borderline west={4pt}{0pt}{accent},
    left=12pt, right=10pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{26}{32}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardbgB,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=1.5pt, titlerule style={accent!40},
    valign=top, drop shadow={opacity=0.15},
  },
  rosecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbgC,
    borderline west={4pt}{0pt}{goldaccent},
    left=12pt, right=10pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{26}{32}\selectfont\bfseries\color{goldaccent},
    coltitle=goldaccent, colbacktitle=cardbgC,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=1.5pt, titlerule style={goldaccent!40},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={5pt}{0pt}{primary},
    left=12pt, right=10pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{26}{32}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=4pt, bottomtitle=4pt,
    valign=top, drop shadow={opacity=0.2},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════
% TITLE BAR
% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=6pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{54}{65}\selectfont\bfseries The History of Books}\\[8pt]
  {\fontsize{30}{36}\selectfont From Manuscripts to Mass Production}\\[6pt]
  {\fontsize{18}{22}\selectfont\color{white!75} A 1,500-Year Data Journey Through the Written Word}
}

% ═══════════════════════════════════════════
% STATS BANNER
% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!12!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=4pt, bottom=4pt,
  valign=center, borderline south={2pt}{0pt}{primary!30},
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.3\linewidth}\centering
    \fcolorbox{accent!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{40}{48}\selectfont\bfseries\color{accent} 1,500}\\[2pt]
      {\fontsize{14}{18}\selectfont\color{textdark} Years of Book Data}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.3\linewidth}\centering
    \fcolorbox{accent!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{40}{48}\selectfont\bfseries\color{accent} $\sim$1440}\\[2pt]
      {\fontsize{14}{18}\selectfont\color{textdark} Gutenberg's Press}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.3\linewidth}\centering
    \fcolorbox{accent!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{40}{48}\selectfont\bfseries\color{accent} 3,500$\times$}\\[2pt]
      {\fontsize{14}{18}\selectfont\color{textdark} Output Increase Since 1440}\vspace{4pt}%
    }}
  \end{minipage}
}

% ═══════════════════════════════════════════
% THE LONG ARC - TIMELINE (DOMINANT, SPAN=2)
% ═══════════════════════════════════════════
\posterbox[
  orangecard, title={The Long Arc of Book Production}
]{name=timeline, column=1, span=2, between=row5 and row12}{
  \posterfig{0.98}{figures/timeline_chart.png}{Estimated European book output from the 6th century to the present (log scale). Sources: Buringh \& Van Zanden (2009); Fink-Jensen (2015).}
}

% ═══════════════════════════════════════════
% LEFT COLUMN: MANUSCRIPT ERA + MIRROR
% ═══════════════════════════════════════════

% Manuscript Era
\posterbox[
  browncard, title={The Manuscript Era}
]{name=manuscripts, column=1, between=row12 and row16}{
  \fontsize{18}{24}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Handwritten on papyrus, parchment, vellum
    \item Growth over \textbf{10 centuries} $\to$ slow, linear
    \item Carolingian Renaissance (9th C) sparked first rise
    \item Rise of universities (12th C) accelerated demand
    \item Peak era: 15th C $\to$ \textbf{700K manuscripts} in Europe
  \end{itemize}
  \vspace{2mm}
  \posterfig{0.95}{figures/manuscript_detail.png}{European manuscript output by century.}
}

% Books as a Mirror of Society
\posterbox[
  highlightcard, title={Books as a Mirror of Society}
]{name=mirror, column=1, between=row16 and row20}{
  \fontsize{18}{24}\selectfont\color{textdark}
  \begin{itemize}[itemsep=6pt]
    \item \textbf{Literacy} $\Rightarrow$ More books $=$ more readers
    \item \textbf{Wealth} $\Rightarrow$ Affordable books $=$ rising prosperity
    \item \textbf{Education} $\Rightarrow$ Schools drive demand
    \item \textbf{Culture} $\Rightarrow$ Religious texts $\to$ secular works over time
  \end{itemize}
  \vspace{3mm}
  \colorbox{accent!20}{\parbox{0.92\linewidth}{%
    \centering\fontsize{16}{20}\selectfont\color{primary}
    \textbf{From elite luxury to mass commodity --- the most important story in the history of human knowledge.}%
  }}
}

% ═══════════════════════════════════════════
% RIGHT COLUMN: GUTENBERG + MODERN
% ═══════════════════════════════════════════

% Gutenberg Revolution
\posterbox[
  rosecard, title={The Gutenberg Revolution}
]{name=gutenberg, column=2, between=row12 and row16}{
  \fontsize{18}{24}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item Johannes Gutenberg, $\sim$1440: movable-type press
    \item \textbf{Single most transformative event} in book history
    \item Prices fell $\Rightarrow$ consumption surged
    \item 50 years post-press: output $\times$15
    \item By 1800s: industrial printing enables mass production
  \end{itemize}
  \vspace{2mm}
  \posterfig{0.95}{figures/gutenberg_impact.png}{Relative book output before and after the printing press.}
}

% Modern Publishing
\posterbox[
  orangecard, title={Modern Publishing \& Consumption}
]{name=modern, column=2, between=row16 and row20}{
  \fontsize{18}{24}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item UNESCO standard: title with $>$49 pages
    \item Vast country-level variation in output
    \item \textbf{UK: 290+} new titles per million people
    \item Income \& education drive differences
    \item Data spans 1500--2009 (Fink-Jensen, 2015)
  \end{itemize}
  \vspace{2mm}
  \posterfig{0.95}{figures/modern_publishing.png}{New book titles per million people by country.}
}

\end{tcbposter}
\end{document}

