% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=6pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{60}{72}\selectfont\bfseries The History of Books}\\[8pt]
  {\fontsize{34}{40}\selectfont From Manuscripts to Mass Production}\\[6pt]
  {\fontsize{20}{24}\selectfont\color{white!75} A 1,500-Year Data Journey Through the Written Word}
}

% ═══════════════════════════════════════════
% STATS BANNER
% ═══════════════════════════════════════════
